#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=8

# Same local env file as setup-oracle.sh (server address, SSH key, secrets).
ENV_FILE="$HOME/.config/oracle-n8n/.env"
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[[ -f "$ENV_FILE" ]] || { warn "missing $ENV_FILE: run scripts/setup-oracle.sh first."; exit 1; }

# ns_of DOMAIN prints its nameservers as seen by public DNS. Google's resolver
# is used because 1.1.1.1 can keep serving the old nameservers for hours.
ns_of() {
  if command -v dig >/dev/null 2>&1; then dig +short NS "$1" @8.8.8.8
  elif command -v nslookup >/dev/null 2>&1; then nslookup -type=NS "$1" 8.8.8.8 2>/dev/null | awk '/nameserver/ {print $NF}'
  else # DNS-over-HTTPS: needs only curl
    curl -s "https://dns.google/resolve?name=$1&type=NS" \
      | grep -oE '"data": ?"[^"]+"' | sed -E 's/.*"([^"]+)"$/\1/'
  fi
}

# dns_status NAME prints Google DNS's answer status for NAME (0 = exists, 3 = NXDOMAIN).
dns_status() {
  curl -s "https://dns.google/resolve?name=$1&type=A" | grep -oE '"Status": ?[0-9]+' | grep -oE '[0-9]+$'
}

banner "Public domain for n8n via Cloudflare Tunnel + Access"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Pick the domain"
say "n8n will live on a subdomain; the parent domain moves its DNS to Cloudflare."
ask N8N_DOMAIN "n8n hostname (e.g. n8n.saepulmalik.my.id):"
N8N_DOMAIN="${N8N_DOMAIN,,}"
write_env N8N_DOMAIN "$N8N_DOMAIN"
ZONE="${N8N_DOMAIN#*.}"
SUB="${N8N_DOMAIN%%.*}"
write_env CF_ZONE "$ZONE"
note "Zone moved to Cloudflare: $ZONE · subdomain for n8n: $SUB"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Note the DNS records you have at Hostinger"
say "Moving nameservers replaces Hostinger's DNS with Cloudflare's. Any record that isn't"
say "copied over (website, email MX, verification TXT) stops working, so list them first."
open_url "https://hpanel.hostinger.com/domains"
step "Open $ZONE → DNS / Nameservers → 'DNS records'."
step "Take a screenshot or note every A, CNAME, MX and TXT record. You'll compare in stage 3."
note "If the domain has no website or email yet, there may be nothing important here."
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Add $ZONE to Cloudflare"
open_url "https://dash.cloudflare.com/"
step "Sign up / sign in. Add a site → 'Connect a domain' (NOT Transfer) → enter $ZONE."
step "Choose the Free plan."
step "Review the DNS records Cloudflare imported: compare with the list from stage 2 and add"
step "anything missing. Do NOT add a record for $N8N_DOMAIN; the tunnel creates it later."
step "Continue until Cloudflare shows two nameservers (like xxx.ns.cloudflare.com)."
ask CF_NS1 "Cloudflare nameserver 1:"
write_env CF_NS1 "${CF_NS1,,}"
ask CF_NS2 "Cloudflare nameserver 2:"
write_env CF_NS2 "${CF_NS2,,}"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Point Hostinger to Cloudflare's nameservers"
if ns_of "$ZONE" 2>/dev/null | grep -qi "${CF_NS1%.}"; then
  printf '  %s✓ %s already uses Cloudflare nameservers%s\n' "$GREEN" "$ZONE" "$RESET"
else
  open_url "https://hpanel.hostinger.com/domains"
  step "Open $ZONE → DNS / Nameservers → 'Change nameservers'."
  step "Pick 'Use custom nameservers' and enter:"
  printf '\n      %s%s%s\n      %s%s%s\n\n' "$BOLD" "$CF_NS1" "$RESET" "$BOLD" "$CF_NS2" "$RESET"
  step "Save. Back in Cloudflare, click 'Check nameservers now'."
  note "Activation takes minutes to a few hours (.my.id is managed by PANDI). Cloudflare emails"
  note "you when the domain is Active. You can Ctrl-C now and re-run this wizard later."
  pause "Press Enter once the nameservers are saved at Hostinger"
  until ns_of "$ZONE" 2>/dev/null | grep -qi "${CF_NS1%.}"; do
    warn "Public DNS still shows: $(ns_of "$ZONE" 2>/dev/null | tr '\n' ' ' || echo '?')"
    if ! confirm "Check again? (No = stop here and re-run later)"; then
      say "Re-run 'bash scripts/setup-domain.sh' once Cloudflare says $ZONE is Active."
      exit 0
    fi
  done
  printf '  %s✓ nameservers now point to Cloudflare%s\n' "$GREEN" "$RESET"
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Create the Cloudflare Tunnel"
open_url "https://one.dash.cloudflare.com/"
step "First visit to Zero Trust: pick a team name and the Free plan (it may ask for a card;"
step "the Free plan isn't charged)."
step "Networks → Tunnels (or Connectors) → 'Create a tunnel' → Cloudflared → name: oracle-n8n."
step "On 'Install and run connectors', pick Docker and copy the command shown."
step "Paste it below (the whole command is fine; only the token after --token is kept)."
step "Don't run that command anywhere: the stack starts cloudflared on the VPS for you."
while :; do
  ask_secret CLOUDFLARE_TUNNEL_TOKEN "Tunnel command or token:"
  CLOUDFLARE_TUNNEL_TOKEN="${CLOUDFLARE_TUNNEL_TOKEN##*--token }"
  CLOUDFLARE_TUNNEL_TOKEN="${CLOUDFLARE_TUNNEL_TOKEN//[[:space:]]/}"
  [[ "$CLOUDFLARE_TUNNEL_TOKEN" =~ ^[A-Za-z0-9_=-]{80,}$ ]] && break
  warn "That doesn't look like a tunnel token (a long base64 string); try again."
done
write_env CLOUDFLARE_TUNNEL_TOKEN "$CLOUDFLARE_TUNNEL_TOKEN"
step "Then add a route: tunnel page → Routes → 'Add route' → 'Published application'"
step "(older UI: 'Public hostnames'). NOT a private network route. Fill in:"
printf '\n      Subdomain %s%s%s · Domain %s%s%s · Path (empty)\n' "$BOLD" "$SUB" "$RESET" "$BOLD" "$ZONE" "$RESET"
printf '      Service URL %shttp://n8n:5678%s  (older UI: type HTTP + URL n8n:5678)\n\n' "$BOLD" "$RESET"
note "'n8n' is the container name inside the Docker network; cloudflared reaches it there."
step "Save. Cloudflare creates the DNS record for $N8N_DOMAIN automatically."
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Lock the editor behind Cloudflare Access"
say "Access asks for a one-time code by email before anyone even sees the n8n login."
say "Webhooks must stay reachable by outside services, so /webhook paths bypass it."
open_url "https://one.dash.cloudflare.com/"
ask CF_ACCESS_EMAIL "Email allowed into the editor:"
write_env CF_ACCESS_EMAIL "$CF_ACCESS_EMAIL"
step "Access → Applications → Add an application → Self-hosted:"
step "  Name: n8n editor · Domain: $N8N_DOMAIN (path empty) · Session: 24h or longer."
step "  Policy: name 'owner', Action Allow, Include → Emails → $CF_ACCESS_EMAIL."
step "  Login method: One-time PIN. Save."
step "Add a second Self-hosted application:"
step "  Name: n8n webhooks · Domain: $N8N_DOMAIN · Path: webhook"
step "  Add another destination/hostname: $N8N_DOMAIN · Path: webhook-test"
step "  Policy: name 'public webhooks', Action Bypass, Include → Everyone. Save."
note "The more specific path wins, so /webhook/* skips the email code while / stays protected."
warn "Bypassed webhooks are public: protect each Webhook node with Header Auth (a secret header)."
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Deploy n8n with the domain"
say "Re-uploads stack/ with the domain settings and starts the cloudflared container."
if confirm "Deploy now?"; then
  "$REPO_DIR/scripts/deploy.sh"
  if [[ "$(dns_status "$N8N_DOMAIN")" != "0" ]]; then
    warn "$N8N_DOMAIN has no DNS record yet. In Cloudflare check: the zone $ZONE is Active, and"
    warn "the tunnel has a public hostname for it (DNS → Records should show a CNAME '$SUB'"
    warn "→ <tunnel-id>.cfargotunnel.com, Proxied). Then re-run this wizard."
  fi
  say "Checking through Cloudflare (DNS can take a minute)…"
  web="" root=""
  for _ in $(seq 1 24); do
    web=$(curl -s -o /dev/null -w '%{http_code}' "https://$N8N_DOMAIN/webhook/__wizard_probe" || true)
    [[ "$web" == "404" ]] && break
    sleep 5
  done
  root=$(curl -s -o /dev/null -w '%{http_code}' "https://$N8N_DOMAIN/" || true)
  [[ "$web" == "000" ]] && warn "000 = this machine can't resolve or reach $N8N_DOMAIN (DNS missing or cached as missing)."
  if [[ "$web" == "404" ]]; then printf '  %s✓ tunnel + webhook bypass work%s (n8n answered 404 for an unknown webhook)\n' "$GREEN" "$RESET"
  else warn "webhook probe answered '$web' (expected 404). 530/1033 = tunnel not connected; 302/403 = bypass app missing."; fi
  if [[ "$root" == "302" || "$root" == "403" ]]; then printf '  %s✓ editor is behind Access%s (HTTP %s)\n' "$GREEN" "$RESET" "$root"
  else warn "editor answered '$root' (expected 302 to the Access login). Check the 'n8n editor' application."; fi
  note "Logs: ssh oracle-n8n 'cd ~/n8n && docker compose logs --tail 30 cloudflared'"
else
  SKIPPED+=("deploy with the domain (stage 7): run scripts/deploy.sh")
fi
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Open n8n on its domain"
open_url "https://$N8N_DOMAIN"
step "Enter $CF_ACCESS_EMAIL, type the code from your inbox, then log in to n8n as usual."
step "OAuth credentials (Gmail etc.): the callback URL n8n shows is now https://$N8N_DOMAIN/...;"
step "register that URL at the provider instead of the localhost one."
note "The SSH tunnel (http://localhost:5678) still works as a fallback if Cloudflare is down."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
